package com.aegis.erp.modules.planilla.inasistencia;import com.aegis.erp.common.exception.*;import com.aegis.erp.common.export.DocumentExportService;import com.aegis.erp.modules.planilla.empleado.EmpleadoOptionResponse;import com.aegis.erp.modules.planilla.entity.*;import com.aegis.erp.modules.planilla.repository.*;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class InasistenciaService{private final InasistenciaRepository inasistencias;private final EmpleadoRepository empleados;private final DocumentExportService exports;private final Clock clock;public InasistenciaService(InasistenciaRepository i,EmpleadoRepository e,DocumentExportService x,Clock c){inasistencias=i;empleados=e;exports=x;clock=c;}@Transactional(readOnly=true)public List<InasistenciaResponse>listar(String search){String q=norm(search);return inasistencias.findAll().stream().map(this::response).filter(x->q.isEmpty()||(x.empleadoNombre()+" "+(x.motivo()==null?"":x.motivo())).toLowerCase(Locale.ROOT).contains(q)).toList();}@Transactional public InasistenciaResponse crear(InasistenciaRequest r,String user){range(r);return save(Inasistencia.crear(empleado(r.empleadoId()),r.fechaInicial(),r.fechaFinal(),optional(r.motivo()),user,LocalDateTime.now(clock)));}@Transactional public InasistenciaResponse modificar(Long id,InasistenciaRequest r,String user){range(r);var e=find(id);e.modificar(empleado(r.empleadoId()),r.fechaInicial(),r.fechaFinal(),optional(r.motivo()),user,LocalDateTime.now(clock));return save(e);}@Transactional public void eliminar(Long id){var e=find(id);try{inasistencias.delete(e);inasistencias.flush();}catch(DataIntegrityViolationException ex){throw new BusinessConflictException("No se puede eliminar la inasistencia porque tiene información asociada.");}}
 @Transactional(readOnly=true)public List<EmpleadoOptionResponse>empleados(String search){String q=norm(search);return empleados.findAll().stream().filter(e->q.isEmpty()||(e.getId()+" "+e.getPersona().getNombre()+" "+e.getPersona().getApellido()).toLowerCase(Locale.ROOT).contains(q)).limit(50).map(e->new EmpleadoOptionResponse(e.getId(),"#"+e.getId()+" — "+e.getPersona().getNombre()+" "+e.getPersona().getApellido())).toList();}@Transactional(readOnly=true)public byte[]excel(String s){return exports.excel("Inasistencias",headers(),rows(s));}@Transactional(readOnly=true)public byte[]pdf(String s){return exports.pdf("Listado de inasistencias",headers(),rows(s));}private List<String>headers(){return List.of("ID","Empleado","Fecha inicial","Fecha final","Motivo","Fecha procesado");}private List<List<?>>rows(String s){return listar(s).stream().<List<?>>map(x->List.of(x.id(),x.empleadoNombre(),x.fechaInicial(),x.fechaFinal(),x.motivo()==null?"":x.motivo(),x.fechaProcesado()==null?"":x.fechaProcesado())).toList();}
 private void range(InasistenciaRequest r){if(r.fechaInicial().isAfter(r.fechaFinal()))throw new BusinessConflictException("La fecha inicial no puede ser posterior a la fecha final.");}private InasistenciaResponse save(Inasistencia e){try{return response(inasistencias.saveAndFlush(e));}catch(DataIntegrityViolationException ex){throw new BusinessConflictException("No fue posible guardar la inasistencia por una restricción de integridad.");}}private InasistenciaResponse response(Inasistencia e){return new InasistenciaResponse(e.getId(),e.getEmpleado().getId(),e.getEmpleado().getPersona().getNombre()+" "+e.getEmpleado().getPersona().getApellido(),e.getFechaInicial(),e.getFechaFinal(),e.getMotivo(),e.getFechaProcesado());}private Inasistencia find(Long id){return inasistencias.findById(id).orElseThrow(()->new ResourceNotFoundException("Inasistencia no encontrada."));}private Empleado empleado(Long id){return empleados.findById(id).orElseThrow(()->new ResourceNotFoundException("Empleado no encontrado."));}private String optional(String s){return s==null||s.isBlank()?null:s.trim();}private String norm(String s){return s==null?"":s.trim().toLowerCase(Locale.ROOT);}}
